"""Longest Happy Prefix — the last value of the KMP prefix function.

Time: O(n)   Space: O(n)
"""


class Solution:
    def longestPrefix(self, s: str) -> str:
        lps = [0] * len(s)
        length = 0
        for i in range(1, len(s)):
            while length and s[i] != s[length]:
                length = lps[length - 1]
            if s[i] == s[length]:
                length += 1
                lps[i] = length
        return s[:lps[-1]]
